156	  for (int i = 1; i < grouped_domain.size(); ++i) {
157	    padded_domain_size *= grouped_domain[i];
158	  }
159	
160	  auto waves = ceildiv(padded_domain_size, wave_size);
161	  auto loop_var = Var("w", waves.dtype());
162	  Array<Var> coord_vars;
163	
164	  for (int i = 0; i < domain.size(); ++i) {
165	    DataType dtype = domain[i].dtype();
