177	    Array<PrimExpr> idxs(grouped_domain.size(), PrimExpr());
178	    PrimExpr rem = loop_var * wave_size + index;
179	
180	    for (int i = grouped_domain.size() - 1; i >= 1; --i) {
181	      idxs.Set(i, truncmod(rem, grouped_domain[i]));
182	      rem = truncdiv(rem, grouped_domain[i]);
183	    }
